package com.example.com.englishai.backend.application.authentication; import com.example.com.englishai.backend.application.ports.*; import com.example.com.englishai.backend.domain.authentication.PasswordResetCode; import org.springframework.beans.factory.annotation.Qualifier; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.UUID;
@Service public class RequestPasswordReset {private final UserRepository users;private final PasswordResetCodeRepository codes;private final PasswordResetCodeGenerator generator;private final PasswordResetCodeHasher hasher;private final EmailSender sender;private final Duration expiration;private final int max;private final Clock clock;public RequestPasswordReset(UserRepository u,PasswordResetCodeRepository c,PasswordResetCodeGenerator g,PasswordResetCodeHasher h,EmailSender s,@Qualifier("passwordResetCodeExpiration") Duration e,@Qualifier("passwordResetMaxAttempts") Integer m,@Qualifier("refreshTokenClock") Clock cl){users=u;codes=c;generator=g;hasher=h;sender=s;expiration=e;max=m;clock=cl;}@Transactional public void execute(String email){var user=users.findByEmailForUpdate(email.trim()).orElse(null);if(user==null)return;var now=OffsetDateTime.ofInstant(clock.instant(),ZoneOffset.UTC);for(var old:codes.findByUserIdForUpdate(user.getId()))if(old.getUsedAt()==null&&old.getInvalidatedAt()==null)codes.save(old.invalidate(now));var raw=generator.generate();codes.save(new PasswordResetCode(UUID.randomUUID(),user.getId(),hasher.hash(raw),now,now.plus(expiration),null,null,0,max));sender.sendEmailVerificationCode(user.getEmail(),raw);}}

